.panel-kicker{color:var(--lime);font-size:8px;font-weight:800;letter-spacing:1.8px}.panel-title{font:800 28px 'Barlow Condensed';margin:7px 0 15px}.overview-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.info-tile{padding:13px;background:#ffffff08;border:1px solid #ffffff0f}.info-tile small{display:block;color:#9da99a;font-size:7px;letter-spacing:1px}.info-tile strong{display:block;font:700 20px 'Barlow Condensed';margin-top:5px}.tile-bar{height:3px;background:#263429;margin-top:8px}.tile-bar span{display:block;height:100%;background:var(--lime)}.panel-row{display:flex;align-items:center;justify-content:space-between;padding:11px 0;border-bottom:1px solid #ffffff12;font-size:10px}.panel-row:last-of-type{border:0}.panel-row span{color:#acb8ab}.small-action{background:var(--lime);border:0;color:#111a0e;padding:9px 13px;font-size:8px;font-weight:900;letter-spacing:1px}.small-action:disabled{opacity:.45}.panel-note{color:#99a597;font-size:9px;line-height:1.6;margin-top:12px}.edit-form{display:grid;grid-template-columns:1fr 1fr;gap:9px}.edit-form label{font-size:8px;color:#99a597;letter-spacing:1px}.edit-form input,.edit-form select{display:block;width:100%;margin-top:5px;background:#101e18;color:#f4f4ec;border:1px solid #ffffff20;padding:9px;font:600 10px 'DM Sans';outline:none}.edit-form .full{grid-column:span 2}.match-screen{position:absolute;z-index:3;inset:0;pointer-events:none}.match-top{position:absolute;top:24px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:12px;pointer-events:auto}.scoreboard{display:flex;align-items:center;gap:15px;background:rgba(7,17,14,.91);border:1px solid #ffffff27;padding:9px 15px;box-shadow:0 10px 35px #0006;backdrop-filter:blur(12px)}.score-team{display:flex;align-items:center;gap:7px;font-size:9px;letter-spacing:1px}.score-crest{width:24px;height:26px;font-size:12px}.scoreboard>strong{font:800 23px 'Barlow Condensed';white-space:nowrap}.scoreboard>strong i{font-style:normal;color:#829081;padding:0 3px}.match-clock{border-left:1px solid #ffffff28;padding-left:13px;display:flex;align-items:center;gap:6px;color:var(--lime);font-size:10px;letter-spacing:.7px}.clock-dot{width:5px;height:5px}.pause-button{width:34px;height:34px;background:rgba(7,17,14,.87);border:1px solid #ffffff27;font-size:15px;color:#f1f3eb}.toast{position:absolute;top:84px;left:50%;transform:translate(-50%,-10px);background:#c8f05d;color:#10180d;padding:8px 14px;font-size:8px;font-weight:900;letter-spacing:1.3px;opacity:0;transition:.3s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.match-bottom{position:absolute;bottom:26px;left:5.25%;right:5.25%;display:flex;align-items:end;justify-content:space-between}.player-indicator{display:flex;align-items:center;gap:10px;padding:9px 13px;background:rgba(7,17,14,.88);border:1px solid #ffffff27;min-width:190px}.player-portrait{display:grid;place-items:center;width:34px;height:38px;background:var(--lime);color:#15200f;font:800 18px 'Barlow Condensed';clip-path:polygon(0 0,100% 0,100% 78%,50% 100%,0 78%)}.player-indicator b,.player-indicator small{display:block}.player-indicator b{font-size:8px;letter-spacing:1px}.player-indicator small{color:#a7b3a5;font-size:7px;margin-top:4px}.stamina{height:3px;width:62px;background:#3c493c;margin-top:6px}.stamina span{height:100%;width:100%;display:block;background:var(--lime);transition:width .5s}.action-hint{background:rgba(7,17,14,.79);padding:9px 12px;color:#c8f05d;font-size:8px;font-weight:800;letter-spacing:1.4px}.touch-controls{display:none;pointer-events:auto;position:absolute;inset:0}.stick-zone{position:absolute;left:5%;bottom:92px;width:130px;height:130px;touch-action:none}.joystick{position:absolute;inset:0;border:1px solid #ffffff42;border-radius:50%;background:#07120e66;touch-action:none;display:grid;place-items:center}.joystick:before{content:'';position:absolute;width:60%;height:60%;border:1px solid #ffffff19;border-radius:50%}.stick-knob{width:44px;height:44px;border-radius:50%;background:#d7f58cbb;border:1px solid #f1ffd5;box-shadow:0 3px 15px #0005}.action-buttons{position:absolute;right:4%;bottom:91px;width:195px;height:164px}.action-btn{position:absolute;border:1px solid #ffffff57;background:#101a16bd;border-radius:50%;width:52px;height:52px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0;touch-action:none;backdrop-filter:blur(6px)}.action-btn span{font-size:19px;line-height:20px}.action-btn small{font-size:6px;font-weight:800;letter-spacing:.5px}.btn-shoot{right:4px;top:52px;width:63px;height:63px;background:#c8f05dcf;color:#14200c;border:0}.btn-pass{right:65px;top:90px}.btn-cross{right:3px;top:0}.btn-tackle{left:3px;top:61px}.btn-sprint{right:76px;top:24px;width:44px;height:44px}.modal{position:absolute;z-index:8;inset:0;display:grid;place-items:center;background:rgba(2,8,6,.78);backdrop-filter:blur(10px)}.modal-card{width:min(360px,calc(100% - 34px));padding:32px;background:#0b1914;border:1px solid #ffffff29;box-shadow:0 30px 90px #0009}.modal-card h2{font:800 45px/.84 'Barlow Condensed';margin:16px 0 12px}.modal-card p{color:#aab5a8;font-size:11px;margin-bottom:20px}.modal-card>.btn-primary,.modal-card>.btn-ghost{width:100%;justify-content:space-between;margin-top:5px;padding-left:13px;padding-right:13px}.modal-card>.btn-ghost{border:1px solid #ffffff20;text-align:left}.event-banner{position:absolute;z-index:6;left:50%;top:32%;transform:translate(-50%,-50%) scale(.9);font:800 clamp(32px,7vw,68px)/1 'Barlow Condensed';letter-spacing:2px;color:#fff;text-shadow:0 5px 35px #000;white-space:nowrap;opacity:0;pointer-events:none}.event-banner.show{animation:banner 2s ease both}.event-banner em{color:var(--lime);font-style:normal}.result-card{text-align:center}.result-card .eyebrow{justify-content:center}.result-score{font:800 48px 'Barlow Condensed';color:var(--lime);margin:18px}.result-card>.btn-primary{justify-content:center}.career-screen,.home-screen,.match-screen{transition:opacity .35s ease}.hidden{opacity:0;pointer-events:none}@keyframes banner{0%{opacity:0;transform:translate(-50%,-20%) scale(.85)}14%,72%{opacity:1;transform:translate(-50%,-50%) scale(1)}100%{opacity:0;transform:translate(-50%,-75%) scale(1.05)}}
@media (max-width:760px){.topbar{top:max(17px,env(safe-area-inset-top));left:5%;right:5%}.home-screen{padding:100px 7% 50px;display:block;overflow:auto}.hero-copy{margin:8vh 0 0;max-width:510px}.hero-copy h1{font-size:clamp(64px,17vw,95px);margin:22px 0 16px}.hero-copy>p{font-size:11px;max-width:300px;line-height:1.6}.hero-actions{margin-top:24px;gap:19px}.hero-footnote{margin-top:30px;font-size:7px}.hero-side{display:none}.vignette{background:linear-gradient(90deg,rgba(3,12,10,.88),rgba(3,12,10,.45)),linear-gradient(0deg,rgba(4,13,11,.7),transparent 40%)}.hero-bottom{left:7%;right:7%;bottom:max(15px,env(safe-area-inset-bottom));font-size:6px}.hero-bottom>span:last-child{display:none}.career-screen{padding:90px 6% 30px}.career-heading h1{font-size:49px}.career-heading>p{max-width:240px;line-height:1.5}.career-layout{display:block;margin-top:20px}.career-tabs{display:grid;grid-template-columns:1fr 1fr;margin-bottom:10px;gap:4px}.career-tabs button{padding:11px 8px;text-align:center;font-size:7px}.career-tabs button span{margin-left:5px}.career-panel{padding:15px;min-height:220px}.back-button{top:-3px;padding:8px;font-size:7px}.match-top{top:max(12px,env(safe-area-inset-top));gap:5px}.scoreboard{gap:7px;padding:7px 9px}.score-team{font-size:7px;gap:4px}.score-crest{width:20px;height:22px;font-size:10px}.scoreboard>strong{font-size:19px}.match-clock{font-size:9px;padding-left:7px}.pause-button{width:30px;height:30px}.match-bottom{left:4%;right:4%;bottom:max(13px,env(safe-area-inset-bottom));align-items:center}.player-indicator{min-width:0;padding:6px 8px;gap:7px}.player-portrait{width:29px;height:32px;font-size:15px}.player-indicator b{font-size:7px}.player-indicator small{font-size:6px}.stamina{width:45px}.action-hint{font-size:6px;padding:7px 6px;max-width:120px}.touch-controls{display:block}.stick-zone{bottom:88px;left:5%;width:110px;height:110px}.joystick{background:#07120e69}.action-buttons{bottom:83px;right:3%;transform:scale(.88);transform-origin:bottom right}.toast{top:60px;font-size:7px}.modal-card{padding:25px}.event-banner{top:34%}}
@media (max-height:590px) and (min-width:761px){.home-screen{padding-top:90px;padding-bottom:35px}.hero-copy h1{font-size:72px;margin:17px 0}.hero-footnote{margin-top:30px}.hero-side{margin-top:0}.career-screen{padding-top:80px}.career-heading h1{font-size:46px;margin:10px 0}.career-layout{margin-top:15px}.career-panel{min-height:190px}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const canvas=$('#pitch');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.22;
const scene=new THREE.Scene();scene.background=new THREE.Color(0x91a49d);scene.fog=new THREE.Fog(0x91a49d,100,245);
const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,420);
const clock=new THREE.Clock();
const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const mats={grass:mat(0x3c7546),line:mat(0xe9eee0,.72),dark:mat(0x17221e),concrete:mat(0x38413c),steel:mat(0x64716a,.48,.42),roof:mat(0x172520,.55,.3),crowd:[0xb6c1b6,0xe6e1d3,0x354f4a,0xc45c44,0xd1ae5e,0x5275a2,0x252c2c].map(c=>mat(c)),red:mat(0xc84935,.66),white:mat(0xe4e5d9,.74),blue:mat(0x397bb0,.66),navy:mat(0x1d3852,.72),skin:[0x8e573d,0xc17e5a,0xe0aa80,0x6a4234,0xb6704e].map(c=>mat(c)),black:mat(0x171b18,.7),ball:mat(0xf4f1df,.36),keeper:mat(0xf0c242,.66)};
const world={scene,renderer,camera, ball:null, players:[], active:null, game:false, paused:false, elapsed:0, homeScore:0, awayScore:0, weather:0, cameraMode:0, rain:null, lastEvent:0, possession:'home', power:0,charging:false, touch:{x:0,z:0,sprint:false}, user:null, aiStrategy:0, homePossession:0};
const saved=JSON.parse(localStorage.getItem('touchline-career')||'null')||{name:'Jamie Hayes',position:'CAM',nationality:'England',age:19,club:'Northbridge FC',clubShort:'NOR',rating:68,apps:0,goals:0,assists:0,training:0,seasons:1,value:1.2,appearance:'Classic',country:'ENG'};world.user=saved;
function makeGrassTexture(){const c=document.createElement('canvas');c.width=512;c.height=512;const x=c.getContext('2d');x.fillStyle='#477d4c';x.fillRect(0,0,512,512);for(let i=0;i<512;i++){x.fillStyle=i%64<32?'rgba(180,205,126,.055)':'rgba(5,35,18,.045)';x.fillRect(0,i,512,1)}for(let i=0;i<1300;i++){x.fillStyle=`rgba(12,44,21,${Math.random()*.15})`;x.fillRect(Math.random()*512,Math.random()*512,1+Math.random()*2,1)}const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(8,6);t.anisotropy=4;return t}
function addBox(parent,w,h,d,material,x,y,z,cast=false){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);m.position.set(x,y,z);m.castShadow=cast;m.receiveShadow=true;parent.add(m);return m}
function stadium(){
 const floor=new THREE.Mesh(new THREE.PlaneGeometry(108,70),new THREE.MeshStandardMaterial({map:makeGrassTexture(),roughness:.92}));floor.rotation.x=-Math.PI/2;floor.position.y=-.12;floor.receiveShadow=true;scene.add(floor);
 const stripe= new THREE.Mesh(new THREE.PlaneGeometry(105,68),new THREE.MeshBasicMaterial({color:0xffffff,transparent:true,opacity:.035}));stripe.rotation.x=-Math.PI/2;stripe.position.y=-.105;scene.add(stripe);
 const lines=new THREE.Group(),Y=.015;function line(w,h,x,z){const o=new THREE.Mesh(new THREE.PlaneGeometry(w,h),mats.line);o.rotation.x=-Math.PI/2;o.position.set(x,Y,z);lines.add(o)}
 line(.14,68,0,0);line(105,.14,0,0);line(.14,68,-52.5,0);line(.14,68,52.5,0);line(16.5,.14,0,-34);line(16.5,.14,0,34);line(.14,16.5,-8.25,-42.25);line(.14,16.5,8.25,-42.25);line(.14,16.5,-8.25,42.25);line(.14,16.5,8.25,42.25);line(5.5,.12,0,-46.5);line(5.5,.12,0,46.5);line(.12,5.5,-2.75,-49.25);line(.12,5.5,2.75,-49.25);line(.12,5.5,-2.75,49.25);line(.12,5.5,2.75,49.25);
 const circle=new THREE.Mesh(new THREE.RingGeometry(9.05,9.2,80),mats.line);circle.rotation.x=-Math.PI/2;circle.position.set(0,Y,0);lines.add(circle);const spot=new THREE.Mesh(new THREE.CircleGeometry(.17,16),mats.line);spot.rotation.x=-Math.PI/2;spot.position.set(0,Y,0);lines.add(spot);
 for(const z of [-52.6,52.6]){const goal=new THREE.Group();const white=mats.line;for(const x of [-3.66,3.66]){const p=new THREE.Mesh(new THREE.CylinderGeometry(.085,.085,2.44,10),white);p.position.set(x,1.22,z);goal.add(p)}const cross=new THREE.Mesh(new THREE.CylinderGeometry(.085,.085,7.4,10),white);cross.rotation.z=Math.PI/2;cross.position.set(0,2.44,z);goal.add(cross);for(let i=0;i<6;i++){const str=addBox(goal,.025,1.8,.025,mat(0xd8ded2,.9),-3.1+i*1.24,.9,z+(z>0?1.4:-1.4));str.material=white}for(let y=0;y<4;y++)addBox(goal,7.1,.025,.025,white,0,.25+y*.52,z+(z>0?1.4:-1.4));scene.add(goal)}
 scene.add(lines);
 // deep, layered grandstands and a crowd that reads as thousands from camera distance
 for(const side of ['north','south']){const sg=new THREE.Group();sg.position.set(0,0,side==='north'?-1:1);for(let tier=0;tier<3;tier++){const r=37+tier*5,base=4+tier*4;const slab=addBox(sg,112,1.3,9,mat(0x49534c),0,base+1,side==='north'?-r:r);slab.rotation.x=side==='north'?-.055:.055;for(let row=0;row<8;row++){const y=base+2+row*.43;const z=(side==='north'?-1:1)*(r-3+row*.27);addBox(sg,111,.18,.52,mat(0x58645c),0,y,z);}
 const count=750;const inst=new THREE.InstancedMesh(new THREE.BoxGeometry(.32,.44,.28),mats.crowd, count);inst.castShadow=false;const dummy=new THREE.Object3D();for(let i=0;i<count;i++){const x=(Math.random()-.5)*107,y=base+3+Math.random()*3.2,z=(side==='north'?-1:1)*(r-2+Math.random()*2);dummy.position.set(x,y,z);dummy.rotation.y=(Math.random()-.5)*.24;dummy.scale.set(.7+Math.random()*.8,.8+Math.random()*.9,.7+Math.random()*.7);dummy.updateMatrix();inst.setMatrixAt(i,dummy.matrix);inst.setColorAt(i,new THREE.Color([0xede8dc,0xc94b36,0x3d6692,0x273b32,0xc6ac71,0x9ca99e][Math.floor(Math.random()*6)]))}sg.add(inst);}}
 for(const side of [-1,1]){for(let tier=0;tier<3;tier++){const z=side*(39+tier*4);const stand=addBox(scene,13+Math.random()*3,7,98,mats.concrete,side*54,7+tier*4,z);stand.rotation.z=side*-.13;const crowd=new THREE.InstancedMesh(new THREE.BoxGeometry(.32,.42,.3),mats.crowd,380);const dummy=new THREE.Object3D();for(let i=0;i<380;i++){dummy.position.set(side*(47+Math.random()*13),5+tier*4+Math.random()*3,(Math.random()-.5)*96);dummy.scale.set(.8,1,.8);dummy.updateMatrix();crowd.setMatrixAt(i,dummy.matrix);crowd.setColorAt(i,new THREE.Color([0xe5e6db,0xd04f37,0x3e668f,0x344c3a,0x9eaa9b][i%5]))}scene.add(crowd)}}
 // roof rings, floodlight pylons and LED ribbon
 for(const side of [-1,1]){addBox(scene,116,1.1,14,mats.roof,0,28,side*42);addBox(scene,108,.25,1.5,mat(0xcce8df,.4,0),0,22,side*31);for(let x of [-46,46]){const pole=addBox(scene,.8,31,.8,mats.steel,side*x,15,side*37);pole.rotation.z=side*.16;const lamp=addBox(scene,8,.35,1.4,mat(0xf5ffe2,.24),side*x,28,side*38);lamp.castShadow=false}}
 const board=addBox(scene,105,1.2,.25,mat(0x28382d),0,.8,-35);const board2=addBox(scene,105,1.2,.25,mat(0x28382d),0,.8,35);for(let z of [-35,35]){const glow=addBox(scene,104,.09,.28,mat(0xc6e965,.4),0,1.08,z);glow.material.emissive=new THREE.Color(0x405e16);glow.material.emissiveIntensity=.9}
}

