function makeMat(color,roughness=.82,metalness=0){return new THREE.MeshStandardMaterial({color,roughness,metalness});}
function addMesh(parent,geometry,material,x=0,y=0,z=0){const mesh=new THREE.Mesh(geometry,material);mesh.position.set(x,y,z);parent.add(mesh);return mesh;}
function initScene(){
  scene=new THREE.Scene();scene.background=new THREE.Color('#76909a');scene.fog=new THREE.Fog('#82969a',105,205);
  camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,350);camera.position.set(45,47,-66);
  renderer=new THREE.WebGLRenderer({canvas:$('#pitch'),antialias:true,alpha:false,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.08;
  scene.add(new THREE.HemisphereLight('#d8e8d8','#26342a',2.1));const sun=new THREE.DirectionalLight('#fff1ce',2.8);sun.position.set(-35,65,-20);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-80;sun.shadow.camera.right=80;sun.shadow.camera.top=100;sun.shadow.camera.bottom=-100;scene.add(sun);
  buildStadium();clock=new THREE.Clock();addEventListener('resize',resize);animate();
}
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);}
function buildStadium(){
  const grass=makeMat('#287847'),darkGrass=makeMat('#246e40'),lineMat=makeMat('#e9efdf');
  addMesh(scene,new THREE.PlaneGeometry(230,260),makeMat('#34423a'),0,-.55,0).rotation.x=-Math.PI/2;
  fieldGroup=new THREE.Group();scene.add(fieldGroup);const pitch=addMesh(fieldGroup,new THREE.PlaneGeometry(68,105),grass,0,0,0);pitch.rotation.x=-Math.PI/2;pitch.receiveShadow=true;
  for(let i=0;i<10;i++){const stripe=addMesh(fieldGroup,new THREE.PlaneGeometry(6.8,105),i%2?grass:darkGrass,-30.6+i*6.8,.012,0);stripe.rotation.x=-Math.PI/2;}
  function line(points,width=.13){const geo=new THREE.BufferGeometry().setFromPoints(points.map(p=>v3(p[0],.035,p[1])));const mesh=new THREE.Line(geo,new THREE.LineBasicMaterial({color:'#e4ebd8'}));fieldGroup.add(mesh);}
  line([[-34,-52.5],[34,-52.5],[34,52.5],[-34,52.5],[-34,-52.5]]);line([[-34,0],[34,0]]);
