 }else{for(const p of world.players){if(p===user)continue;const teamChaser=nearestPlayer(p.team,ballPos);if(p===teamChaser){p.target.copy(ballPos);p.target.x+=p.team==='home'?-.4:.4;}else p.target.copy(p.homePos).lerp(ballPos,.06);}}
 if(user){if(user===ball.owner){user.target.copy(user.group.position);}else if(!carrier)user.target.copy(ballPos);else if(carrier.team!==user.team){if(user.group.position.distanceTo(carrier.group.position)<18)user.target.copy(carrier.group.position);else user.target.copy(user.homePos).lerp(carrier.group.position,.13);}else user.target.copy(user.homePos).lerp(ballPos,.12);}
 for(const p of world.players){if(p===user){p.group.position.x+=p.velocity.x*dt;p.group.position.z+=p.velocity.z*dt;}else{const delta=p.target.clone().sub(p.group.position);delta.y=0;const dist=delta.length();if(dist>.45){delta.normalize();const top=(p===carrier?5.5:4.7)*(p.stamina>.15?1:.75);p.velocity.x+=(delta.x*top-p.velocity.x)*Math.min(1,dt*3.1);p.velocity.z+=(delta.z*top-p.velocity.z)*Math.min(1,dt*3.1);p.group.rotation.y=Math.atan2(p.velocity.x,p.velocity.z);}else p.velocity.multiplyScalar(Math.max(0,1-dt*4));p.group.position.x+=p.velocity.x*dt;p.group.position.z+=p.velocity.z*dt;p.stamina=Math.max(.35,p.stamina-dt*.0018);}p.group.position.x=clamp(p.group.position.x,-32.6,32.6);p.group.position.z=clamp(p.group.position.z,-51,51);p.anim+=dt*(2.5+Math.hypot(p.velocity.x,p.velocity.z)*1.3);const run=clamp(Math.hypot(p.velocity.x,p.velocity.z)/5,0,1);p.legs.forEach((l,i)=>{l.pivot.rotation.x=Math.sin(p.anim+i*Math.PI)*.68*run;l.joint.rotation.x=Math.max(0,Math.sin(p.anim+i*Math.PI-1))*.67*run;});p.arms.forEach((a,i)=>a.pivot.rotation.x=Math.sin(p.anim+(1-i)*Math.PI)*.42*run);p.model.position.y=Math.abs(Math.sin(p.anim*2))*.045*run;p.model.rotation.z=Math.sin(p.anim)*.035*run;}
 for(let i=0;i<world.players.length;i++)for(let j=i+1;j<world.players.length;j++){const a=world.players[i],b=world.players[j],dx=b.group.position.x-a.group.position.x,dz=b.group.position.z-a.group.position.z,d=Math.hypot(dx,dz);if(d<.58&&d>.001){const push=(.58-d)*.09;a.group.position.x-=dx/d*push;b.group.position.x+=dx/d*push;a.group.position.z-=dz/d*push;b.group.position.z+=dz/d*push;}}
 if(ball.owner){const p=ball.owner,speed=Math.hypot(p.velocity.x,p.velocity.z),dir=speed>.3?v3(p.velocity.x,0,p.velocity.z).normalize():v3(Math.sin(p.group.rotation.y),0,Math.cos(p.group.rotation.y));ball.group.position.set(p.group.position.x+dir.x*.58,.23,p.group.position.z+dir.z*.58);ball.velocity.set(p.velocity.x,0,p.velocity.z);}
 else{ball.velocity.y-=9.81*dt;ball.group.position.addScaledVector(ball.velocity,dt);ball.velocity.x*=Math.pow(.985,dt*60);ball.velocity.z*=Math.pow(.985,dt*60);if(ball.group.position.y<.22){ball.group.position.y=.22;if(Math.abs(ball.velocity.y)>1.1)ball.velocity.y*=-.42;else ball.velocity.y=0;ball.velocity.x*=.975;ball.velocity.z*=.975;}ball.spin*=.994;ball.group.rotation.x+=ball.velocity.z*dt*1.2;ball.group.rotation.z-=ball.velocity.x*dt*1.2;ball.group.rotation.y+=ball.spin*dt*.08;
  for(const p of world.players){const d=p.group.position.distanceTo(ball.group.position);if(d<.85&&ball.group.position.y<1.35){if(p.isKeeper&&Math.abs(ball.velocity.z)>.1){if(Math.random()<.76){ball.velocity.multiplyScalar(-.25);ball.velocity.x+=(Math.random()-.5)*7;ball.velocity.y=2.5;event('GREAT SAVE',1200);ball.owner=null;}else giveBall(p);}else if(ball.velocity.length()<15||p===user||Math.random()<.4){giveBall(p);if(p===user)world.active=p;break;}}}}
