 if(ball.group.position.z>52.5||ball.group.position.z< -52.5){const scoring=ball.group.position.z>52.5?'home':'away';if(Math.abs(ball.group.position.x)<3.7&&ball.group.position.y<2.55)goal(scoring);else{ball.group.position.z=Math.sign(ball.group.position.z)*52;ball.velocity.z*=-.52;ball.owner=null;if(Math.abs(ball.group.position.x)>34){ball.group.position.x=Math.sign(ball.group.position.x)*33;ball.velocity.x*=-.45;}}}if(ball.group.position.x>34||ball.group.position.x< -34){ball.group.position.x=clamp(ball.group.position.x,-33.5,33.5);ball.velocity.x*=-.45;}
