}

function goal(team){if(performance.now()-world.lastGoal<2500)return;world.lastGoal=performance.now();if(team==='home')world.homeScore++;else world.awayScore++;$('#score').innerHTML=`${world.homeScore} <i>—</i> ${world.awayScore}`;const scoredBy=world.ball.lastTouch==='home'?world.active:null;if(team==='home'&&scoredBy?.number===10)world.matchGoals=(world.matchGoals||0)+1;banner(team==='home'?'GOAL!':'GOAL · RIVERSIDE');event(team==='home'?'THE CROWD ERUPTS':'RIVERSIDE FIND THE NET',2800);world.players.forEach(p=>p.velocity.multiplyScalar(.1));world.ball.owner=null;world.ball.group.position.set(0,.24,0);world.ball.velocity.set(0,0,0);setTimeout(()=>{if(world.game&&!world.paused){const next=team==='home'?'away':'home',c=world.players.find(q=>q.team===next&&q.number===10)||nearestPlayer(next,v3());giveBall(c);world.active=world.userPlayer;}},1800);}
function finishMatch(){world.game=false;$('#result-score').textContent=`${world.homeScore} — ${world.awayScore}`;const win=world.homeScore>world.awayScore,draw=world.homeScore===world.awayScore;$('#result-title').innerHTML=win?'A STATEMENT<br><em>PERFORMANCE.</em>':draw?'A HARD-FOUGHT<br><em>POINT.</em>':'THE WORK<br><em>CONTINUES.</em>';$('#result-copy').textContent=win?'A brilliant result. Your journey is just getting started.':draw?'A competitive debut. There is more to come.':'A difficult first outing. Take it to training and come back stronger.';career.apps++;career.goals+=world.matchGoals||0;career.points+=2+(win?1:0);career.value=+(career.value+(win?.12:.05)).toFixed(2);persist();updateCareerUI();$('#result-modal').classList.remove('hidden');$('#touch-controls').style.display='none';}
function pause(value){world.paused=value;$('#pause-modal').classList.toggle('hidden',!value);if(value){$('#camera-button').textContent=`CAMERA: ${['BROADCAST','TACTICAL','PLAYER'][world.cameraMode]} ↻`;$('#weather-button').textContent=`WEATHER: ${['CLEAR','RAIN','HEAVY RAIN'][world.weather]} ↻`;}}
function cycleCamera(){world.cameraMode=(world.cameraMode+1)%3;if(world.paused)pause(true);event(`CAMERA · ${['BROADCAST','TACTICAL','PLAYER'][world.cameraMode]}`);}
function cycleWeather(){world.weather=(world.weather+1)%3;scene.fog.density=world.weather===2?.012:.006;if(world.rain.material){world.rain.material.opacity=world.weather===0?0:world.weather===1?.4:.72;world.rain.material.size=world.weather===2?.11:.075;}$('#weather-button').textContent=`WEATHER: ${['CLEAR','RAIN','HEAVY RAIN'][world.weather]} ↻`;}
function animate(){requestAnimationFrame(animate);const dt=Math.min(.04,clock.getDelta());if(world.game)updateMatch(dt);renderer.render(scene,camera);}
$('#play-match').addEventListener('click',startMatch);$('#career-button').addEventListener('click',showCareer);$('#career-back').addEventListener('click',showHome);$$('.career-tabs button').forEach(button=>button.addEventListener('click',()=>renderCareer(button.dataset.tab)));$('#pause-button').addEventListener('click',()=>pause(true));$('#resume-button').addEventListener('click',()=>pause(false));$('#camera-button').addEventListener('click',cycleCamera);$('#weather-button').addEventListener('click',cycleWeather);$('#quit-button').addEventListener('click',()=>{world.game=false;$('#pause-modal').classList.add('hidden');showHome();});$('#result-continue').addEventListener('click',showCareer);
updateCareerUI();initScene();showHome();

content.text:
.panel-kicker{color:var(--lime);font-size:8px;font-weight:800;letter-spacing:1.8px}
}.overview-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
}.info-tile small{display:block;color:#9da99a;font-size:7px;letter-spacing:1px}
}.tile-bar{height:3px;background:#263429;margin-top:8px}
}.panel-row{display:flex;align-items:center;justify-content:space-between;padding:11px 0;border-bottom:1px solid #ffffff12;font-size:10px}
}.panel-row span{color:#acb8ab}
}.small-action:disabled{opacity:.45}
}.edit-form{display:grid;grid-template-columns:1fr 1fr;gap:9px}
}.edit-form input,.edit-form select{display:block;width:100%;margin-top:5px;background:#101e18;color:#f4f4ec;border:1px solid #ffffff20;padding:9px;font:600 10px 'DM Sans';outline:none}
}.match-screen{position:absolute;z-index:3;inset:0;pointer-events:none}
}.scoreboard{display:flex;align-items:center;gap:15px;background:rgba(7,17,14,.91);border:1px solid #ffffff27;padding:9px 15px;box-shadow:0 10px 35px #0006;backdrop-filter:blur(12px)}
}.score-crest{width:24px;height:26px;font-size:12px}
}.scoreboard>strong i{font-style:normal;color:#829081;padding:0 3px}
}.clock-dot{width:5px;height:5px}
}.toast{position:absolute;top:84px;left:50%;transform:translate(-50%,-10px);background:#c8f05d;color:#10180d;padding:8px 14px;font-size:8px;font-weight:900;letter-spacing:1.3px;opacity:0;transition:.3s;white-space:nowrap}
}.match-bottom{position:absolute;bottom:26px;left:5.25%;right:5.25%;display:flex;align-items:end;justify-content:space-between}
}.player-portrait{display:grid;place-items:center;width:34px;height:38px;background:var(--lime);color:#15200f;font:800 18px 'Barlow Condensed';clip-path:polygon(0 0,100% 0,100% 78%,50% 100%,0 78%)}
}.player-indicator b{font-size:8px;letter-spacing:1px}
}.stamina{height:3px;width:62px;background:#3c493c;margin-top:6px}
}.action-hint{background:rgba(7,17,14,.79);padding:9px 12px;color:#c8f05d;font-size:8px;font-weight:800;letter-spacing:1.4px}
}.stick-zone{position:absolute;left:5%;bottom:92px;width:130px;height:130px;touch-action:none}
}.joystick:before{content:'';position:absolute;width:60%;height:60%;border:1px solid #ffffff19;border-radius:50%}
}.action-buttons{position:absolute;right:4%;bottom:91px;width:195px;height:164px}
}.action-btn span{font-size:19px;line-height:20px}
}.btn-shoot{right:4px;top:52px;width:63px;height:63px;background:#c8f05dcf;color:#14200c;border:0}
}.btn-cross{right:3px;top:0}
}.btn-sprint{right:76px;top:24px;width:44px;height:44px}
}.modal-card{width:min(360px,calc(100% - 34px));padding:32px;background:#0b1914;border:1px solid #ffffff29;box-shadow:0 30px 90px #0009}
}.modal-card p{color:#aab5a8;font-size:11px;margin-bottom:20px}
}.modal-card>.btn-ghost{border:1px solid #ffffff20;text-align:left}
}.event-banner.show{animation:banner 2s ease both}
}.result-card{text-align:center}
}.result-score{font:800 48px 'Barlow Condensed';color:var(--lime);margin:18px}
}.career-screen,.home-screen,.match-screen{transition:opacity .35s ease}
}14%,72%{opacity:1;transform:translate(-50%,-50%) scale(1)}
}.home-screen{padding:100px 7% 50px;display:block;overflow:auto}
}.hero-copy h1{font-size:clamp(64px,17vw,95px);margin:22px 0 16px}
}.hero-actions{margin-top:24px;gap:19px}
}.hero-side{display:none}
}.hero-bottom{left:7%;right:7%;bottom:max(15px,env(safe-area-inset-bottom));font-size:6px}

