1: function goal(team){if(performance.now()-world.lastGoal<2500)return;world.lastGoal=performance.now();if(team==='home')world.homeScore++;else world.awayScore++;$('#score').innerHTML=`${world.homeScore} <i>—</i> ${world.awayScore}`;const scoredBy=world.ball.lastTouch==='home'?world.active:null;if(team==='home'&&scoredBy?.number===10)world.matchGoals=(world.matchGoals||0)+1;banner(team==='home'?'GOAL!':'GOAL · RIVERSIDE');event(team==='home'?'THE CROWD ERUPTS':'RIVERSIDE FIND THE NET',2800);world.players.forEach(p=>p.velocity.multiplyScalar(.1));world.ball.owner=null;world.ball.group.position.set(0,.24,0);world.ball.velocity.set(0,0,0);setTimeout(()=>{if(world.game&&!world.paused){const next=team==='home'?'away':'home',c=world.players.find(q=>q.team===next&&q.number===10)||nearestPlayer(next,v3());giveBall(c);world.active=world.userPlayer;}},1800);}
2: function finishMatch(){world.game=false;$('#result-score').textContent=`${world.homeScore} — ${world.awayScore}`;const win=world.homeScore>world.awayScore,draw=world.homeScore===world.awayScore;$('#result-title').innerHTML=win?'A STATEMENT<br><em>PERFORMANCE.</em>':draw?'A HARD-FOUGHT<br><em>POINT.</em>':'THE WORK<br><em>CONTINUES.</em>';$('#result-copy').textContent=win?'A brilliant result. Your journey is just getting started.':draw?'A competitive debut. There is more to come.':'A difficult first outing. Take it to training and come back stronger.';career.apps++;career.goals+=world.matchGoals||0;career.points+=2+(win?1:0);career.value=+(career.value+(win?.12:.05)).toFixed(2);persist();updateCareerUI();$('#result-modal').classList.remove('hidden');$('#touch-controls').style.display='none';}
3: function pause(value){world.paused=value;$('#pause-modal').classList.toggle('hidden',!value);if(value){$('#camera-button').textContent=`CAMERA: ${['BROADCAST','TACTICAL','PLAYER'][world.cameraMode]} ↻`;$('#weather-button').textContent=`WEATHER: ${['CLEAR','RAIN','HEAVY RAIN'][world.weather]} ↻`;}}
4: function cycleCamera(){world.cameraMode=(world.cameraMode+1)%3;if(world.paused)pause(true);event(`CAMERA · ${['BROADCAST','TACTICAL','PLAYER'][world.cameraMode]}`);}
5: function cycleWeather(){world.weather=(world.weather+1)%3;scene.fog.density=world.weather===2?.012:.006;if(world.rain.material){world.rain.material.opacity=world.weather===0?0:world.weather===1?.4:.72;world.rain.material.size=world.weather===2?.11:.075;}$('#weather-button').textContent=`WEATHER: ${['CLEAR','RAIN','HEAVY RAIN'][world.weather]} ↻`;}
6: function animate(){requestAnimationFrame(animate);const dt=Math.min(.04,clock.getDelta());if(world.game)updateMatch(dt);renderer.render(scene,camera);}
7: $('#play-match').addEventListener('click',startMatch);$('#career-button').addEventListener('click',showCareer);$('#career-back').addEventListener('click',showHome);$$('.career-tabs button').forEach(button=>button.addEventListener('click',()=>renderCareer(button.dataset.tab)));$('#pause-button').addEventListener('click',()=>pause(true));$('#resume-button').addEventListener('click',()=>pause(false));$('#camera-button').addEventListener('click',cycleCamera);$('#weather-button').addEventListener('click',cycleWeather);$('#quit-button').addEventListener('click',()=>{world.game=false;$('#pause-modal').classList.add('hidden');showHome();});$('#result-continue').addEventListener('click',showCareer);
