import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js';

const $ = (selector) => document.querySelector(selector);
const $$ = (selector) => [...document.querySelectorAll(selector)];
const v3 = (x=0,y=0,z=0) => new THREE.Vector3(x,y,z);
const clamp = (n,min,max) => Math.max(min,Math.min(max,n));
const FIELD = { x: 100, z: 64, goal: 7.32 };
const STORAGE_KEY = 'touchline-career';
const defaultCareer = {name:'Jamie Hayes', age:19, position:'Attacking Midfielder', club:'Northbridge FC', rating:68, apps:0, goals:0, assists:0, value:1.2, training:0, season:1};
let career;
try { career = {...defaultCareer, ...JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}')}; } catch { career = {...defaultCareer}; }
const world = {game:false, paused:false, players:[], active:null, userPlayer:null, homeScore:0, awayScore:0, matchGoals:0, lastGoal:0, matchSeconds:0, cameraMode:0, weather:0, keys:{}, stick:v3(), sprint:false, rain:null, ball:null, homeTeam:'home'};
let scene, camera, renderer, clock;
const materials = {};

function persist(){ try { localStorage.setItem(STORAGE_KEY, JSON.stringify(career)); } catch(error) { console.warn('Career save unavailable',error); } }
function event(message,duration=1700){const el=$('#toast');if(!el)return;el.textContent=message;el.classList.add('show');clearTimeout(event.timer);event.timer=setTimeout(()=>el.classList.remove('show'),duration);}
function banner(message){const el=$('#event-banner');el.textContent=message;el.classList.add('show');clearTimeout(banner.timer);banner.timer=setTimeout(()=>el.classList.remove('show'),2200);}
function showHome(){ $('#home').classList.remove('hidden');$('#career-screen').classList.add('hidden');$('#match-screen').classList.add('hidden');$('#pause-modal').classList.add('hidden');$('#result-modal').classList.add('hidden');updateCareerUI(); }
function showCareer(){ $('#home').classList.add('hidden');$('#career-screen').classList.remove('hidden');$('#match-screen').classList.add('hidden');renderCareer('overview'); }
function updateCareerUI(){
  const name=career.name||defaultCareer.name,parts=name.trim().split(/\s+/);$('#player-name').innerHTML=`${parts[0]||'Jamie'}<br>${parts.slice(1).join(' ')||'Hayes'}`;$('#profile-initial').textContent=(parts[0]||'J')[0].toUpperCase();$('#player-role').textContent=`${career.position.toUpperCase()} · ${career.age}`;$('#player-rating').textContent=career.rating;$('#club-name').textContent=career.club.toUpperCase();$('#club-crest').textContent=(career.club[0]||'N').toUpperCase();$('#stat-apps').textContent=career.apps;$('#stat-goals').textContent=career.goals;$('#stat-assists').textContent=career.assists;$('#stat-value').textContent=`€${career.value.toFixed(1)}m`;$('#home-short').textContent=career.club.slice(0,3).toUpperCase();$('#controlled-name').textContent=`${parts[0][0]}. ${parts.at(-1).toUpperCase()}`;$('#controlled-pos').textContent=`CAM · ${career.rating}`;
}
function renderCareer(tab){
  $$('.career-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));const panel=$('#career-panel');
  if(tab==='overview') panel.innerHTML=`<div class="panel-kicker">SEASON ${String(career.season).padStart(2,'0')} · NORTHBRIDGE FC</div><h2 class="panel-title">SEASON OVERVIEW</h2><div class="overview-grid"><div class="info-tile"><small>APPEARANCES</small><strong>${career.apps}</strong><div class="tile-bar"><span style="width:${Math.min(100,career.apps*8)}%"></span></div></div><div class="info-tile"><small>GOALS / ASSISTS</small><strong>${career.goals} / ${career.assists}</strong><div class="tile-bar"><span style="width:${Math.min(100,(career.goals+career.assists)*12)}%"></span></div></div><div class="info-tile"><small>PLAYER RATING</small><strong>${career.rating} OVR</strong><div class="tile-bar"><span style="width:${career.rating}%"></span></div></div><div class="info-tile"><small>MARKET VALUE</small><strong>€${career.value.toFixed(1)}m</strong><div class="tile-bar"><span style="width:${Math.min(100,career.value*12)}%"></span></div></div></div><p class="panel-note">Your first league fixture is ready. Train to improve your attributes, then take your form onto the pitch.</p>`;
  if(tab==='training') panel.innerHTML=`<div class="panel-kicker">PLAYER DEVELOPMENT</div><h2 class="panel-title">TRAINING GROUND</h2><div class="panel-row"><span>Technical session</span><strong>+1 OVR · 1 session</strong></div><div class="panel-row"><span>Sessions completed</span><strong>${career.training}</strong></div><p class="panel-note">Focused technical work sharpens your touch and passing. Training takes place between fixtures.</p><button id="train-button" class="small-action" ${career.training>=8?'disabled':''}>${career.training>=8?'SEASON LIMIT REACHED':'COMPLETE SESSION'}</button>`;
  if(tab==='transfers') panel.innerHTML=`<div class="panel-kicker">YOUR REPRESENTATION</div><h2 class="panel-title">TRANSFER CENTRE</h2><div class="panel-row"><span>Current club</span><strong>${career.club.toUpperCase()}</strong></div><div class="panel-row"><span>Interest</span><strong>${career.rating>=75?'SCOUTS WATCHING':'NO OFFERS YET'}</strong></div><p class="panel-note">Put in strong performances and build your value to attract clubs. The window opens at the end of the season.</p><button id="transfer-button" class="small-action" ${career.rating<75?'disabled':''}>${career.rating<75?'IMPROVE YOUR RATING':'VIEW CLUB INTEREST'}</button>`;
  if(tab==='profile') panel.innerHTML=`<div class="panel-kicker">PLAYER IDENTITY</div><h2 class="panel-title">EDIT PLAYER</h2><form id="edit-form" class="edit-form"><label>PLAYER NAME<input name="name" maxlength="28" value="${escapeHtml(career.name)}" required></label><label>AGE<input name="age" type="number" min="16" max="40" value="${career.age}"></label><label class="full">POSITION<select name="position">${['Attacking Midfielder','Striker','Winger','Central Midfielder'].map(p=>`<option ${career.position===p?'selected':''}>${p}</option>`).join('')}</select></label><button class="small-action full">SAVE PLAYER</button></form>`;
  $('#train-button')?.addEventListener('click',()=>{career.training++;career.rating=Math.min(99,career.rating+1);career.value=+(career.value+.1).toFixed(1);persist();renderCareer('training');updateCareerUI();event('SESSION COMPLETE · RATING IMPROVED');});
  $('#transfer-button')?.addEventListener('click',()=>event('YOUR AGENT IS SPEAKING TO CLUBS'));
  $('#edit-form')?.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.currentTarget);career.name=String(d.get('name')).trim()||defaultCareer.name;career.age=clamp(Number(d.get('age'))||19,16,40);career.position=String(d.get('position'));persist();updateCareerUI();event('PLAYER PROFILE SAVED');});
}
function escapeHtml(text){return String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}

function initScene(){
  const canvas=$('#pitch');renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;
  scene=new THREE.Scene();scene.background=new THREE.Color(0x10251a);scene.fog=new THREE.FogExp2(0x10251a,.006);camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,500);clock=new THREE.Clock();
  scene.add(new THREE.HemisphereLight(0xc9e4c4,0x263628,2));const sun=new THREE.DirectionalLight(0xfff1d0,2.4);sun.position.set(-25,55,-35);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);scene.add(sun);
  materials.grass=new THREE.MeshStandardMaterial({color:0x28633c,roughness:.92});materials.line=new THREE.MeshBasicMaterial({color:0xe6f0d7});materials.home=new THREE.MeshStandardMaterial({color:0xe8e8d8,roughness:.72});materials.away=new THREE.MeshStandardMaterial({color:0x403fba,roughness:.7});materials.ball=new THREE.MeshStandardMaterial({color:0xf4f3e8,roughness:.55});
  buildStadium();buildPitch();buildRain();camera.position.set(0,73,102);camera.lookAt(0,0,0);window.addEventListener('resize',resize);bindInput();animate();
}
function buildStadium(){
  const ground=new THREE.Mesh(new THREE.PlaneGeometry(240,190),new THREE.MeshStandardMaterial({color:0x15251d,roughness:1}));ground.rotation.x=-Math.PI/2;ground.position.y=-.12;ground.receiveShadow=true;scene.add(ground);
  for(const side of [-1,1]){const stand=new THREE.Mesh(new THREE.BoxGeometry(132,13,18),new THREE.MeshStandardMaterial({color:side===-1?0x374039:0x29352f,roughness:.86}));stand.position.set(0,6.1,side*47);scene.add(stand);for(let row=0;row<5;row++){const stripe=new THREE.Mesh(new THREE.BoxGeometry(130,.4,1.2),new THREE.MeshStandardMaterial({color:row%2?0x9caa85:0xc2c9a7}));stripe.position.set(0,1.1+row*2.15,side*38.2);scene.add(stripe);}}
  for(const side of [-1,1]){const stand=new THREE.Mesh(new THREE.BoxGeometry(18,13,78),new THREE.MeshStandardMaterial({color:0x303b34,roughness:.9}));stand.position.set(side*58,6.1,0);scene.add(stand);}
  const roofMat=new THREE.MeshStandardMaterial({color:0x18251e,roughness:.8});for(const side of [-1,1]){const roof=new THREE.Mesh(new THREE.BoxGeometry(142,1.2,23),roofMat);roof.position.set(0,13,side*48);scene.add(roof);}
  const crowdGeo=new THREE.BufferGeometry(),pts=[];for(let i=0;i<1700;i++){const side=Math.random()<.5?-1:1;pts.push((Math.random()-.5)*122,1+Math.random()*9,side*(39+Math.random()*8));}crowdGeo.setAttribute('position',new THREE.Float32BufferAttribute(pts,3));scene.add(new THREE.Points(crowdGeo,new THREE.PointsMaterial({color:0xc2c8a9,size:.34,sizeAttenuation:true})));
}
function line(x1,z1,x2,z2,y=.035){const dx=x2-x1,dz=z2-z1,len=Math.hypot(dx,dz);const m=new THREE.Mesh(new THREE.BoxGeometry(len,.035,.12),materials.line);m.position.set((x1+x2)/2,y,(z1+z2)/2);m.rotation.y=-Math.atan2(dz,dx);scene.add(m);return m;}
function buildPitch(){
  const pitch=new THREE.Mesh(new THREE.PlaneGeometry(FIELD.x,FIELD.z),materials.grass);pitch.rotation.x=-Math.PI/2;pitch.receiveShadow=true;scene.add(pitch);
  for(let i=0;i<10;i++){const stripe=new THREE.Mesh(new THREE.PlaneGeometry(FIELD.x/10,FIELD.z),new THREE.MeshBasicMaterial({color:i%2?0x2d7042:0x28633c}));stripe.rotation.x=-Math.PI/2;stripe.position.set(-FIELD.x/2+FIELD.x/20+i*FIELD.x/10,.012,0);scene.add(stripe);}
  const x=FIELD.x/2,z=FIELD.z/2;line(-x,-z,x,-z);line(-x,z,x,z);line(-x,-z,-x,z);line(x,-z,x,z);line(0,-z,0,z);const circle=new THREE.Mesh(new THREE.TorusGeometry(9.15,.065,5,80),materials.line);circle.rotation.x=Math.PI/2;circle.position.y=.045;scene.add(circle);
  for(const side of [-1,1]){const boxX=side*33.5;line(boxX,-20.16,side*x,-20.16);line(boxX,20.16,side*x,20.16);line(boxX,-20.16,boxX,20.16);const sixX=side*42;line(sixX,-9.16,side*x,-9.16);line(sixX,9.16,side*x,9.16);line(sixX,-9.16,sixX,9.16);const goal=new THREE.Group(),post=new THREE.Mesh(new THREE.CylinderGeometry(.13,.13,FIELD.goal,8),new THREE.MeshStandardMaterial({color:0xecefe2,metalness:.2}));for(const gz of [-FIELD.goal/2,FIELD.goal/2]){const p=new THREE.Mesh(new THREE.CylinderGeometry(.14,.14,2.5,8),post.material);p.position.set(side*x,1.25,gz);goal.add(p);}const bar=new THREE.Mesh(new THREE.BoxGeometry(.2,.2,FIELD.goal),post.material);bar.position.set(side*x,FIELD.goal,0);goal.add(bar);scene.add(goal);}
}
function buildRain(){const count=500,positions=new Float32Array(count*3);for(let i=0;i<count;i++){positions[i*3]=(Math.random()-.5)*125;positions[i*3+1]=Math.random()*35;positions[i*3+2]=(Math.random()-.5)*95;}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.BufferAttribute(positions,3));const mat=new THREE.PointsMaterial({color:0xcde6ef,size:.08,transparent:true,opacity:0,sizeAttenuation:true});world.rain=new THREE.Points(geo,mat);scene.add(world.rain);}

