scene.add(world.rain);}
function makePlayer(team,number,position){
  const group=new THREE.Group(),color=team==='home'?0xe8e8d8:0x403fba,shirt=new THREE.MeshStandardMaterial({color,roughness:.72}),shorts=new THREE.MeshStandardMaterial({color:team==='home'?0x202923:0x201e55,roughness:.8}),skin=new THREE.MeshStandardMaterial({color:0xc99069,roughness:.9}),sock=new THREE.MeshStandardMaterial({color:team==='home'?0xe9e9df:0x4846be});
  const torso=new THREE.Mesh(new THREE.CapsuleGeometry(.48,.75,3,7),shirt);torso.position.y=1.35;torso.castShadow=true;group.add(torso);const head=new THREE.Mesh(new THREE.SphereGeometry(.27,8,7),skin);head.position.y=2.06;head.castShadow=true;group.add(head);const short=new THREE.Mesh(new THREE.BoxGeometry(.78,.45,.5),shorts);short.position.y=.79;group.add(short);
  for(const z of [-.21,.21]){const leg=new THREE.Mesh(new THREE.CylinderGeometry(.13,.12,.58,6),sock);leg.position.set(0,.35,z);group.add(leg);const boot=new THREE.Mesh(new THREE.BoxGeometry(.18,.12,.3),new THREE.MeshStandardMaterial({color:0x171916}));boot.position.set(.03,.07,z+.04);group.add(boot);}
  const badge=new THREE.Mesh(new THREE.CircleGeometry(.16,8),new THREE.MeshBasicMaterial({color:team==='home'?0x263628:0xe9e8d7}));badge.position.set(-.03,1.42,.489);group.add(badge);group.position.copy(position);group.traverse(o=>{if(o.isMesh)o.castShadow=true;});scene.add(group);
  return {team,number,group,velocity:v3(),home:position.clone(),stamina:100,role:number===10?'CAM':number===9?'ST':'CM'};
}
function createPlayers(){
  world.players=[];const formation=[[-43,-25,0],[-31,-23,-17],[-31,-8,0],[-31,8,0],[-31,23,17],[-12,-22,-9],[-12,-8,0],[-12,8,0],[-12,22,9],[8,0,0],[35,0,0]];
  for(const team of ['home','away'])formation.forEach(([x,z,offset],i)=>{const dir=team==='home'?1:-1;const pos=v3(x*dir,0,z);if(i===0)pos.set(-45*dir,0,0);else if(i===10)pos.set(34*dir,0,0);const p=makePlayer(team,[1,2,4,5,3,6,8,11,7,10,9][i],pos);p.home.copy(pos);world.players.push(p);});
  world.userPlayer=world.players.find(p=>p.team==='home'&&p.number===10);world.active=world.userPlayer;updateIndicator();
}
function makeBall(){const geometry=new THREE.SphereGeometry(.24,14,12),mesh=new THREE.Mesh(geometry,materials.ball);mesh.castShadow=true;scene.add(mesh);const seams=new THREE.Mesh(new THREE.TorusGeometry(.17,.012,4,12),new THREE.MeshBasicMaterial({color:0x24251e}));seams.position.copy(mesh.position);seams.rotation.x=.8;mesh.add(seams);return {group:mesh,velocity:v3(),owner:null,lastTouch:'home'};}
function updateIndicator(){if(!world.active)return;$('#controlled-name').textContent=world.active.number===10?`${career.name.split(/\s+/)[0][0]}. ${career.name.split(/\s+/).at(-1).toUpperCase()}`:`${world.active.team==='home'?'NORTHBRIDGE':'RIVERSIDE'} #${world.active.number}`;$('#controlled-pos').textContent=`${world.active.role} · ${world.active.team==='home'?career.rating:66}`;}
function startMatch(){
  world.homeScore=world.awayScore=world.matchSeconds=world.matchGoals=0;world.game=true;world.paused=false;world.lastGoal=0;$('#score').innerHTML='0 <i>—</i> 0';$('#clock').textContent='00:00';$('#home').classList.add('hidden');$('#career-screen').classList.add('hidden');$('#match-screen').classList.remove('hidden');$('#pause-modal').classList.add('hidden');$('#result-modal').classList.add('hidden');
  if(!world.players.length)createPlayers();else world.players.forEach(p=>{p.group.position.copy(p.home);p.velocity.set(0,0,0);p.stamina=100;});
  world.ball=world.ball||makeBall();world.ball.group.position.set(0,.24,0);world.ball.velocity.set(0,0,0);giveBall(world.players.find(p=>p.team==='home'&&p.number===10));world.active=world.userPlayer;updateIndicator();$('#touch-controls').style.display='';banner('KICK OFF');event('WASD / ARROWS MOVE · SPACE SHOOT');clock.getDelta();
}
function giveBall(player){if(!player||!world.ball)return;world.ball.owner=player;world.ball.lastTouch=player.team;world.ball.velocity.set(0,0,0);}
function nearestPlayer(team,target){let best=null,distance=Infinity;for(const p of world.players)if(p.team===team){const d=p.group.position.distanceToSquared(target);if(d<distance){distance=d;best=p;}}return best;}
function passBall(cross=false){const p=world.active;if(!world.game||!p||world.ball.owner!==p)return;const teammates=world.players.filter(q=>q.team===p.team&&q!==p);let mate=teammates.sort((a,b)=>{const da=a.group.position.distanceToSquared(p.group.position),db=b.group.position.distanceToSquared(p.group.position);return da-db;})[0];if(cross)mate=teammates.filter(q=>Math.abs(q.group.position.z)<14).sort((a,b)=>a.group.position.x-b.group.position.x)[0]||mate;let dir=mate?mate.group.position.clone().sub(p.group.position):v3(1,0,0);dir.y=0;dir.normalize();if(p.team==='away')dir.x=-dir.x;world.ball.owner=null;world.ball.lastTouch=p.team;world.ball.group.position.copy(p.group.position).add(v3(0,1.3,0));world.ball.velocity.copy(dir).multiplyScalar(cross?19:14);world.ball.velocity.y=cross?4:1.6;event(cross?'CROSSING BALL':'PASS');}
function shootBall(){const p=world.active;if(!world.game||!p)return;if(world.ball.owner!==p){if(p.team==='home'&&world.ball.group.position.distanceTo(p.group.position)<2.2)giveBall(p);else return;}const dir=v3(p.team==='home'?1:-1,0,-p.group.position.z*.012);dir.normalize();world.ball.owner=null;world.ball.lastTouch=p.team;world.ball.group.position.copy(p.group.position).add(v3(dir.x*.8,1.1,dir.z*.8));world.ball.velocity.copy(dir).multiplyScalar(23);world.ball.velocity.y=4.2;event('SHOT ON GOAL');}
function tackle(){if(!world.game||!world.active)return;const opponent=world.ball.owner;if(opponent&&opponent.team!==world.active.team&&world.active.group.position.distanceTo(opponent.group.position)<3.2){giveBall(world.active);event('CLEAN TACKLE');}else if(!opponent&&world.ball.group.position.distanceTo(world.active.group.position)<2.8){giveBall(world.active);event('BALL RECOVERED');}else event('CLOSE DOWN');}
function switchPlayer(){const target=world.ball.owner&&world.ball.owner.team==='away'?world.ball.owner.group.position:world.ball.group.position;const candidates=world.players.filter(p=>p.team==='home').sort((a,b)=>a.group.position.distanceToSquared(target)-b.group.position.distanceToSquared(target));world.active=candidates.find(p=>p!==world.active)||world.userPlayer;world.userPlayer=world.active;updateIndicator();}
function action(name){if(name==='shoot')shootBall();if(name==='pass')passBall();if(name==='cross')passBall(true);if(name==='tackle')tackle();if(name==='switch')switchPlayer();}
function handleGoal(team){if(performance.now()-world.lastGoal<2500)return;world.lastGoal=performance.now();if(team==='home')world.homeScore++;else world.awayScore++;$('#score').innerHTML=`${world.homeScore} <i>—</i> ${world.awayScore}`;if(team==='home'&&world.ball.lastTouch==='home')world.matchGoals++;banner(team==='home'?'GOAL!':'GOAL · RIVERSIDE');event(team==='home'?'THE CROWD ERUPTS':'RIVERSIDE FIND THE NET',2800);world.players.forEach(p=>p.velocity.multiplyScalar(.1));world.ball.owner=null;world.ball.group.position.set(0,.24,0);world.ball.velocity.set(0,0,0);setTimeout(()=>{if(world.game&&!world.paused){const next=team==='home'?'away':'home',c=world.players.find(q=>q.team===next&&q.number===10)||nearestPlayer(next,v3());giveBall(c);world.active=world.userPlayer;}},1500);}

