function aiShoot(player){const dir=v3(player.team==='home'?1:-1,0,0);world.ball.owner=null;world.ball.lastTouch=player.team;world.ball.group.position.copy(player.group.position).add(v3(0,1.1,0));world.ball.velocity.copy(dir).multiplyScalar(20);world.ball.velocity.y=3.5;}
function updateBall(dt){const ball=world.ball;if(ball.owner){const p=ball.owner;const dir=v3(Math.sin(p.group.rotation.y),0,Math.cos(p.group.rotation.y));ball.group.position.copy(p.group.position).addScaledVector(dir,.85);ball.group.position.y=.27+Math.abs(Math.sin(world.matchSeconds*11))*.06;ball.velocity.set(0,0,0);return;}
  ball.velocity.y-=9.8*dt;ball.group.position.addScaledVector(ball.velocity,dt);if(ball.group.position.y<.24){ball.group.position.y=.24;if(ball.velocity.y< -1.3)ball.velocity.y*=-.42;else ball.velocity.y=0;ball.velocity.x*=Math.pow(.985,dt*60);ball.velocity.z*=Math.pow(.985,dt*60);}ball.group.rotation.x+=ball.velocity.z*dt;ball.group.rotation.z-=ball.velocity.x*dt;
  const x=ball.group.position.x,z=ball.group.position.z;if(Math.abs(x)>FIELD.x/2+.5){if(Math.abs(z)<FIELD.goal/2){handleGoal(x>0?'home':'away');return;}ball.group.position.x=Math.sign(x)*(FIELD.x/2-.6);ball.velocity.x*=-.45;}
  if(Math.abs(z)>FIELD.z/2+.4){ball.group.position.z=Math.sign(z)*(FIELD.z/2-.4);ball.velocity.z*=-.55;}
  if(ball.group.position.y<.5&&ball.velocity.length()<3){const p=nearestPlayer(ball.lastTouch==='home'?'away':'home',ball.group.position);if(p&&p.group.position.distanceTo(ball.group.position)<1.35)giveBall(p);}
}
function updateMatch(dt,elapsedDt=dt){if(world.paused)return;world.matchSeconds+=elapsedDt;const elapsed=Math.min(5400,Math.floor(world.matchSeconds*20)),mins=String(Math.floor(elapsed/60)).padStart(2,'0'),secs=String(elapsed%60).padStart(2,'0');$('#clock').textContent=`${mins}:${secs}`;if(world.matchSeconds>=270){finishMatch();return;}
  const p=world.active;if(p){let x=(world.keys.KeyD||world.keys.ArrowRight?1:0)-(world.keys.KeyA||world.keys.ArrowLeft?1:0)+world.stick.x;let z=(world.keys.KeyS||world.keys.ArrowDown?1:0)-(world.keys.KeyW||world.keys.ArrowUp?1:0)+world.stick.z;const len=Math.hypot(x,z);if(len>1){x/=len;z/=len;}const moving=len>.08,sprint=world.sprint||world.keys.ShiftLeft||world.keys.ShiftRight,speed=sprint&&p.stamina>0?8.6:5.8;if(moving){p.velocity.x+=(x*speed-p.velocity.x)*Math.min(1,dt*10);p.velocity.z+=(z*speed-p.velocity.z)*Math.min(1,dt*10);p.group.position.x+=p.velocity.x*dt;p.group.position.z+=p.velocity.z*dt;p.group.rotation.y=Math.atan2(p.velocity.x,p.velocity.z);p.stamina=Math.max(0,p.stamina-(sprint?dt*14:-dt*6));}else{p.velocity.multiplyScalar(Math.max(0,1-dt*7));p.group.position.addScaledVector(p.velocity,dt);p.stamina=Math.min(100,p.stamina+dt*4);}p.group.position.x=clamp(p.group.position.x,-49,49);p.group.position.z=clamp(p.group.position.z,-31,31);$('#stamina-fill').style.width=`${p.stamina}%`;$('#action-hint').textContent=world.ball.owner?.team==='home'?'ATTACKING · BUILD UP':'DEFENDING · WIN IT BACK';}
  updateAI(dt);updateBall(dt);
  if(world.rain.material.opacity>0){const arr=world.rain.geometry.attributes.position.array;for(let i=1;i<arr.length;i+=3){arr[i]-=dt*34;if(arr[i]<0)arr[i]=32;}world.rain.geometry.attributes.position.needsUpdate=true;}
  let target=v3(0,0,0),height=73;if(world.cameraMode===1){target=world.ball.group.position.clone();height=92;}if(world.cameraMode===2){target=world.active.group.position.clone();height=44;target.x+=world.active.team==='home'?9:-9;}const desired=v3(target.x,height,target.z+(world.cameraMode===2?35:100));camera.position.lerp(desired,Math.min(1,dt*2));camera.lookAt(target.x,0,target.z);
}
function finishMatch(){world.game=false;$('#result-score').textContent=`${world.homeScore} — ${world.awayScore}`;const win=world.homeScore>world.awayScore,draw=world.homeScore===world.awayScore;$('#result-title').innerHTML=win?'A STATEMENT<br><em>PERFORMANCE.</em>':draw?'A HARD-FOUGHT<br><em>POINT.</em>':'THE WORK<br><em>CONTINUES.</em>';$('#result-copy').textContent=win?'A brilliant result. Your journey is just getting started.':draw?'A competitive debut. There is more to come.':'A difficult first outing. Take it to training and come back stronger.';career.apps++;career.goals+=world.matchGoals;career.points=(career.points||0)+(win?3:draw?1:0);career.value=+(career.value+(win?.12:.05)).toFixed(2);persist();updateCareerUI();$('#result-modal').classList.remove('hidden');$('#touch-controls').style.display='none';}
function pause(value){world.paused=value;$('#pause-modal').classList.toggle('hidden',!value);if(value){$('#camera-button').textContent=`CAMERA: ${['BROADCAST','TACTICAL','PLAYER'][world.cameraMode]} ↻`;$('#weather-button').textContent=`WEATHER: ${['CLEAR','RAIN','HEAVY RAIN'][world.weather]} ↻`;}}
function cycleCamera(){world.cameraMode=(world.cameraMode+1)%3;if(world.paused)pause(true);event(`CAMERA · ${['BROADCAST','TACTICAL','PLAYER'][world.cameraMode]}`);}
function cycleWeather(){world.weather=(world.weather+1)%3;scene.fog.density=world.weather===2?.012:.006;if(world.rain.material){world.rain.material.opacity=world.weather===0?0:world.weather===1?.4:.72;world.rain.material.size=world.weather===2?.11:.075;}$('#weather-button').textContent=`WEATHER: ${['CLEAR','RAIN','HEAVY RAIN'][world.weather]} ↻`;}
function resize(){if(!renderer)return;renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();}
function animate(){requestAnimationFrame(animate);const elapsed=clock.getDelta(),dt=Math.min(.04,elapsed);if(world.game)updateMatch(dt,elapsed);renderer.render(scene,camera);}
function bindInput(){
  window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;world.keys[e.code]=true;if(e.code==='Escape'){if(world.game)pause(!world.paused);}else if(world.game&&!world.paused){if(e.code==='Space')shootBall();if(e.code==='KeyE')passBall();if(e.code==='KeyC')passBall(true);if(e.code==='KeyX')tackle();if(e.code==='KeyV')switchPlayer();}});
  window.addEventListener('keyup',e=>{world.keys[e.code]=false;});window.addEventListener('blur',()=>{world.keys={};world.sprint=false;world.stick.set(0,0,0);});
  $('#play-match').addEventListener('click',startMatch);$('#career-button').addEventListener('click',showCareer);$('#career-back').addEventListener('click',showHome);$$('.career-tabs button').forEach(button=>button.addEventListener('click',()=>renderCareer(button.dataset.tab)));
  $('#pause-button').addEventListener('click',()=>pause(true));$('#resume-button').addEventListener('click',()=>pause(false));$('#camera-button').addEventListener('click',cycleCamera);$('#weather-button').addEventListener('click',cycleWeather);$('#quit-button').addEventListener('click',()=>{world.game=false;$('#pause-modal').classList.add('hidden');$('#touch-controls').style.display='none';showHome();});$('#result-continue').addEventListener('click',showCareer);
  const stick=$('#joystick'),knob=stick.querySelector('.stick-knob');let pointer=null;stick.addEventListener('pointerdown',e=>{pointer=e.pointerId;stick.setPointerCapture(pointer);updateStick(e);});stick.addEventListener('pointermove',e=>{if(e.pointerId===pointer)updateStick(e);});const release=e=>{if(e.pointerId!==pointer)return;pointer=null;world.stick.set(0,0,0);knob.style.transform='translate(0,0)';};stick.addEventListener('pointerup',release);stick.addEventListener('pointercancel',release);
  function updateStick(e){const rect=stick.getBoundingClientRect(),cx=rect.left+rect.width/2,cy=rect.top+rect.height/2,dx=e.clientX-cx,dy=e.clientY-cy,r=rect.width*.36,d=Math.hypot(dx,dy),scale=d>r?r/d:1;world.stick.set(dx*scale/r,dy*scale/r,0);knob.style.transform=`translate(${dx*scale}px,${dy*scale}px)`;}
  $$('[data-action]').forEach(button=>{const name=button.dataset.action;button.addEventListener('pointerdown',e=>{e.preventDefault();button.classList.add('pressed');if(name==='sprint')world.sprint=true;else action(name);});const stop=e=>{button.classList.remove('pressed');if(name==='sprint')world.sprint=false;};button.addEventListener('pointerup',stop);button.addEventListener('pointercancel',stop);button.addEventListener('pointerleave',stop);});
}
